/*绝句-烤冷面大王*/

/*禁止商用、二传*/
/*🧊默认是390px适配，其他适配需要修改【头像/头像框的大小/位置】+【三元素/名字/时间戳的左右】，有标注🌷*/




/*字体导入*/
@import url("https://fontsapi.zeoseven.com/237/main/result.css");
@import url("https://fontsapi.zeoseven.com/256/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/309/main/result.css");
@import url("https://fontsapi.zeoseven.com/970/main/result.css");



body,
html,
input,
textarea,
select,
button
 {
  font-family:'undefined', 'KingHwaOldSong'!important;
}

/*===by墨千尾老师，顶栏部分===*/
#top-bar {
    position: fixed !important;
    top: 0;
    left: 0;
    width: 100%;
    height: 40px;
    background: #FCFDED !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #FCFDED !important;
    z-index: 7;
    pointer-events: auto;
}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 8;
    pointer-events: none;
}


/*顶栏图标*/
#top-settings-holder .drawer-icon:before {
    font-size: 20px !important;
    font-weight: 500 !important;
    content: "…";
    color:#000;
}

#top-settings-holder .drawer-icon.openIcon:before {
    content: "「」" !important;
    font-size: 20px !important;
}


/*===底栏===*/
#send_form {
  min-height: 100px !important;
  height: auto !important;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  background-image: url(https://i.postimg.cc/kMvkkgZd/IMG-5612.jpg) !important;
  background-repeat:no-repeat!important;
  background-size: 100% 100% !important;
  background-position: center !important;
  border-radius: 0 !important;
  overflow: hidden !important;
  border: 1px solid #D9C8A9 !important;
  box-shadow: 0 0 8px rgba(255,255,255,0.3) !important;
}


#options_button::before,
#extensionsMenuButton::before,
#quick-reply-rocket-button i::before,
#send_but::before,
#mes_stop i::before {
  color: #999 !important;
}


/*byN老师*/
#form_sheld {
  position: absolute;
  bottom: 10px; /* 调整上下 */
}

#send_form {
  width: 96%; /* 调整宽度 */
}

/* 最后一条消息与底栏间距 */
#chat {
  padding-bottom: 80px !important;
}

/* 输入长文本时底栏不挡正文by咩野 */
#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
  position: static;
}


/* 输入框样式 */
#send_form #send_textarea {
    width: 100% !important;
    max-width: 100% !important;
    transform: scale(1) !important;
    transform-origin: center !important;
    border-radius: 6px !important;
    background-color: #fff !important;
    border: none !important;

}


/* ==== by墨千尾老师，输入框提示文字自定义 ==== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    font-family: "XuanZongTi", serif !important;
    content: "泥融飞燕子，沙暖睡鸳鸯";/*🌷输入框自定义文字*/
    color: #000!important;
    position: absolute; 
    left: 55%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.6em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/*——分割线——*/
hr {
    all: unset !important;
    display: block !important;
    visibility: visible !important;
    height: auto !important;
    text-align: center !important;
    margin: 10px 0 !important;
}

hr::after {
    content: "「春风花草香」" !important;/*🌷分割线自定义*/
    font-family: "XuanZongTi", serif !important;
    color: #000 !important;
    font-size: 16px !important;
}


/*===聊天气泡===*/
/* by12老师，文本框与下一个头像框隔开 */
.mes {
  margin-bottom: 7em !important; 
  clear: both !important; 
}

/* by墨千尾老师，让消息框里的文字铺满消息框 */
.mes .mes_text {
    width: 100%;
    padding: 10px 35px 0px 20px;/*🌷文字边距*/
    margin: 0px 5px 0px 5px;
    position: relative;
    z-index: 9999 !important;
}

/* bynini老师，聊天气泡 */
.mes {
    width: 100% !important;
    max-width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    margin-top: 0px !important;
    margin-bottom: auto;
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0!important;
    box-shadow: none !important;
    padding-top: 0px !important;
    padding-bottom: 150px !important;
    padding-left: 3px !important;
    padding-right: 2px !important;



  background-image:
  url("https://i.postimg.cc/C5mzkrqw/IMG-5747.png"),
  url("https://i.postimg.cc/G288bBRH/IMG-5613.png"),
  url("https://i.postimg.cc/y8sZ0Ym5/IMG-5612.png");
   background-position:
  center top,
  center bottom,
  center 200px;

background-size:
  100% auto,
  100% auto,
  100% calc(100% - 200px);

background-repeat:
  no-repeat,
  no-repeat,
  no-repeat;
}

/*----🌷🌷🌷🌷🌷🌷🌷头像+三元素+名字、时间戳⬇️🌷🌷🌷🌷🌷🌷🌷----*/
/*推荐调整顺序：①调整头像框大小➡️②头像大小/位置➡️③头像框+头像位置*/

/* —头像外层容器— */
#chat .mes .avatar {
  position: relative !important;
  width: 250px !important;
  height: 250px !important;
  /*🌷③头像框+头像位置⬇️*/
  top: 12px;
  left: -68px;

  pointer-events: none !important;
}

/* 头像 */
#chat .mes .avatar img {
  position: absolute;
  /*🌷②头像大小⬇️*/
  width: 175px !important;
  height: 175px !important;

  /*🌷②头像位置⬇️*/
  top:6px !important;
  left: 17px !important;

  /*🌷头像显示区域⬇️*/
  object-position: 50% 20%;/*左右、上下，左右没什么用，主要调整上下*/

  border-radius: 50%;
  overflow: visible;
  flex-shrink: 0;
  z-index: 1 !important; 
  border-radius: 50%;
  box-shadow: 0 0 4px 1px rgba(255, 255, 255, 0);
}

/* 头像框 —— 装饰层 */
#chat .mes .avatar::before {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  /*🌷①头像框大小⬇️*/
  width: 200px !important;
  height: 200px !important;

  background-image: url("https://i.postimg.cc/Cxdw6LWc/IMG-5746.png");
  background-repeat: no-repeat !important;
  background-size: 100% 100% !important;
  z-index: 9 !important;
  pointer-events: none !important;
}  


/* 三元素 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    position: absolute !important;
    z-index: 999 !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important; 
    width: 20px !important; 
    min-width: auto !important;
    height: auto !important;
    font-size: 10px !important; 
    color: #000 !important; 
    line-height: 1.1 !important;     
    padding: 0 !important;
    margin: 0 !important;
    background: none !important;
    border: none !important;
    opacity: 1;
    white-space: nowrap !important;
    pointer-events: none; 
    writing-mode: vertical-lr !important;
    text-orientation: upright !important;
}


/*🌷三元素位置，调整left即可⬇️*/
/*楼层*/
.mes .mesIDDisplay {
  top: 80px !important;
  left: 220px!important;
}

/*计时器*/
.mes .mes_timer {
  top: 80px !important;
  left: 260px !important;
}

/*字符*/
.mes .tokenCounterDisplay {
  top: 80px !important;
  left: 300px !important;
}



/* 角色名字 */
.name_text {
  font-family: "XuanZongTi", serif !important;
  position: absolute !important;
  width: 100% !important;
  display: block !important;
  font-size: 15px !important;
  text-align: left !important;
/* 🌷角色名字位置⬇️ */
  margin-left: 210px !important;
  margin-top: -225px!important;

  z-index: 999 !important;
}

/*名字换行*/
.name_text {
  display: block !important;
  width: 140px !important;       /* 控制在多少像素处换行 */
  white-space: normal !important;
  word-break: break-all !important;
  overflow-wrap: break-word !important;
}


/*时间戳*/
.mes .timestamp {
  position: absolute !important;
  width: auto !important;
  display: block !important;
  font-size: 10px !important;
  text-align: left !important;
  /* 🌷时间戳位置⬇️ */
  margin-left: 190px !important;
  margin-top: -240px !important;


  z-index: 999 !important;
  /* 竖向排列（文字直立） */
  writing-mode: vertical-lr;
  text-orientation: upright;
  white-space: nowrap;
}


/*----🌷🌷🌷🌷🌷🌷🌷头像+三元素+名字、时间戳⬆️🌷🌷🌷🌷🌷🌷🌷----*/




/*思维链内文字*/
.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;    /* 文字 离 顶部 的距离 */
    --bottom-padding: 1rem; /* 文字 离 底部 的距离 */
    --left-padding: 1rem;     /* 文字 离 左边 的距离 */
    --right-padding: 0.1rem;  /* 文字 离 右边 的距离 */

    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/*思维链*/
/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
  background: transparent !important; /* 背景改为透明 */
  border: none !important; /* 移除边框 */
  box-shadow: none !important; /* 移除阴影 */
  border-radius: 0; /* 移除圆角 */
  backdrop-filter: none !important; 
  -webkit-backdrop-filter: none !important; 
  padding: 0 !important; /* 移除内边距 */
  margin-bottom: 0 !important; /* 移除底部外边距 */
  color: var(--reasoning-text) !important; /* 字体颜色自定义 */
  font-size: 1em !important;/* 字体大小 */
  display: inline-flex !important;
  align-items: center !important;
  transition: none !important; 
}

/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}

/*来自N老师*/
.mes_reasoning_header_title::before {
    font-family: "XuanZongTi", serif !important;
    content: "绝句" !important; /* 🌷思维链自定义文字 */
    width: auto !important;
    height: auto !important;
    background: none !important;
    font-size: 35px !important;
    color: #000 !important; /* 文字颜色 */
    display: inline-block !important;
    vertical-align: middle !important;
 position: absolute !important;
    /* 🌷思维链位置⬇️ */
    left: 20px !important;  /* 往右挪（正）、左（负） */
    top: -37px !important; /* 往下挪 */
}

.mes_reasoning_header_title {
    font-size: 0 !important;
}

/* 强制思维链标题横排 */
.mes_reasoning_header_title,
.mes_reasoning_header_title::before {
  writing-mode: horizontal-tb !important;
  text-orientation: initial !important;
  white-space: nowrap !important;
}


/*小铅笔+三个点图标统一替换改为文字*/
/*基于nini老师的代码二改*/
/* 隐藏原图标和文字 */
.mes_edit > i,
.extraMesButtonsHint > i {
    display: none !important;
}

/* 按钮容器基础样式（作为文字载体） */
.mes_edit,
.extraMesButtonsHint {
    background: none !important;
    width: auto !important;
    height: auto !important;
    transition: transform 0.2s ease;
    cursor: pointer;
    text-shadow: none !important;
    box-shadow: none !important;
    padding: 0 0px!important;
    margin: 0 5px !important;
    position: relative !important;
    z-index: 9999 !important;
    font-size: 14px !important;
    color: #000 !important; /* 文字颜色 */
}

.mes_buttons {
  position: relative !important;
  left: -13px !important;/*🌷小铅笔+三个点左右位置*/
}

/* 三个点 */
.extraMesButtonsHint::before {
  font-family: 'XiangcuiDazijitiW15', "香萃打字机体" !important;
    content: "闲章" !important; /*🌷三个点自定义文字*/
}

/* 小铅笔 */
.mes_edit::before {
  font-family: 'XiangcuiDazijitiW15', "香萃打字机体" !important;
    content: "改墨" !important; /*🌷小铅笔自定义文字*/
}

/* 悬停效果 */
.mes_edit:hover,
.extraMesButtonsHint:hover {
    transform: scale(1.15) !important;
    opacity: 0.8 !important;
}

/* 清除图标灰色阴影 */
.mes_edit,
.extraMesButtonsHint {
    filter: none !important; 
    opacity: 1 !important; 
}
.mes_edit::before,
.extraMesButtonsHint::before {
    filter: brightness(1) contrast(100%) !important;
}



/*——切页——*/
.swipe_left::before {
  font-family: "XuanZongTi", serif !important;
  content: '辞' !important;/*🌷左箭头自定义*/
  color: #000 !important;
  font-size: 16px !important;
}
.swipe_right::before {
  font-family: "XuanZongTi", serif !important;
  content: '遇' !important;/*🌷右箭头自定义*/
  color: #000 !important;
  font-size: 16px !important;
}
.swipe_left:hover, .swipe_right:hover {
  transform: scale(1.1);
}
.swipes-counter { 
  color: #000;
  opacity: 1 !important;
  transform: translateY(50px) !important;
}

.swipe_right, .swipe_left {
  opacity: 1 !important;
  background: none !important;
  background-image: none !important;
  background-repeat: no-repeat;
  background-position: center;
  transition: transform 0.2s ease;
  width: 30px;
  height: 30px;
  transform: translateY(50px) !important;
  display: flex;
  align-items: center;
  justify-content: center;
}



/* --- 折叠面板按键  --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 20px !important; 
    height: 20px !important; 
    background: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer;
    filter: none !important; 
    opacity: 1 !important; 
    color: #000 !important; 
    border: none !important; 
    box-shadow: none !important;
    font-size: 16px !important;
    font-weight: bold !important;
}

.inline-drawer-icon::before {
  font-family: "XuanZongTi", serif !important;
    content: "启" !important;
    color: #000 !important;
    background: none !important;
    background-image: none !important;
    width: auto !important;
    height: auto !important;
    filter: none !important;
    opacity: 1 !important; 
    text-shadow: none !important;
}

.inline-drawer-icon:hover::before {
    transform: scale(1.2) !important;
}



/*===来自12老师，收藏区===*/
/* 收藏区左右滑动 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  height: calc(var(--avatar-base-height) + 10px);
}

body.big-avatars #HotSwapWrapper > div {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
  height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: #000 !important; 
  border-radius: 5px; 
}
.character_select.is_fav .avatar {
  outline: 2px solid #000 !important;
}

/* 收藏角色名字 */
.character_select.is_fav .ch_name {
  color: #000 !important;
  text-shadow: 0 0 6px #fff, 0 0 12px #000, 0 0 24px #000 !important;
}

/*提示词管理byserein老师 */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #000 !important;
    background: #fcfded !important;
    background-size: 100%;
    border-radius: 0px 0px 0px 0px;
    border: 1px solid #D4C8A8 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    border-radius: 15px !important;
    padding: 5px !important;
}
.completion_prompt_manager_prompt .fa-asterisk,
.completion_prompt_manager_prompt .fa-square-poll-horizontal,
.completion_prompt_manager_prompt .fa-syringe,
.completion_prompt_manager_prompt .fa-thumb-tack,
.fa-xs.fa-solid.fa-robot {
    color: #333 !important;
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #666 !important;
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager .completion_prompt_manager_header div,
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: #333 !important;
}
.inline-drawer-header .inline-drawer-icon {
    color: #333 !important;
    transform: scale(0.8);
}



/* 预设底板  */
#completion_prompt_manager, 
#completion_prompt_manager_list {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    background: #FCFDED center/cover !important;
    border-color: #D9C8A9 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover {
    background: #F7F2E0 !important;
    background-size: cover !important; 
    background-position: center !important; 
    border-color: #C0A886 !important;
    transform: translateY(-2px); 
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.08) !important;
    cursor: pointer;
}



/* ===== 通用 UI 组件  ===== */
.menu_button, .right_menu_button {
    background-color: #FCFDED!important;
    color: #333 !important;
    border: 1px solid #E5D9BB !important;
    border-radius: 10px !important;
    transition: background-color 0.3s ease, transform 0.2s ease !important;
}

.menu_button:hover, .right_menu_button:hover {
    color: #000;
    background-color: #F7F2E0 !important;
    transform: translateY(-2px);
}

.avatar-container.interactable.selected {
    background: #FCFDED !important;
    background-size: cover;
    border: 1px solid #D9C8A9 !important;
}

.text_pole, select, input[type="text"], input[type="number"], input[type="search"], 
#settingsSearch, .popup textarea, #description_textarea, #firstmessage_textarea, 
.edit_textarea.mdHotkeys, .reasoning_edit_textarea, 
.select2-container--default .select2-selection--single, 
.select2-container--default .select2-selection--multiple {
    background-color: #FCFDED !important;
    padding: 1px !important;
    border: 1px solid #E5D9BB !important;
    border-radius: 0px !important;
}

::selection { background: #E5D9BB; color: #000; }

dialog.popup, #select_chat_popup, select, .list-group, .select2-dropdown, 
#options, #options-content, #extensionsMenu { box-shadow: none !important; }

.select2-selection__choice {
    background-color: #FCFDED !important;
    border: 1px solid #E5D9BB !important;
}
.select2-selection__choice__display,
.select2-selection__choice__remove {
    background: none !important;
    color: #333 !important;
}

/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 15px !important;
    height: 15px !important;
    background: #ccc  !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: brightness(1.2) !important;
    -webkit-filter: brightness(1.2) !important;
}


/* 去阴影 */
.fa-pencil-alt,
.fa-pencil,
.fa-ellipsis-h,
.fa-ellipsis,
.fa-pencil-alt:hover,
.fa-pencil:hover,
.fa-ellipsis-h:hover,
.fa-ellipsis:hover {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
  border: none !important;
  outline: none !important;
  background-color: transparent !important;
}
/* 去阴影，小眼睛、小星星 */
.menu_button, .fa-eye, .fa-ranking-star {
    text-shadow: none !important;
    box-shadow: none !important;
    filter: none !important; 
}

/*哈基米赞助去阴影别动！*/
/* 1. 彻底清除所有图标的文字阴影 */
.fa-solid, .fa-regular, .fa-brands, i {
    text-shadow: none !important;
    filter: none !important;
}

/* 2. 针对圆形按钮容器*/
.menu_button, .drawer-content i, .fa-button {
